// archive-index.js — 归档索引工具模块，被上层服务调用（上层负责从消息队列/任务系统取归档名后传入）
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// 弱防御：仅拦截常见 SQL 关键字，可被注释符/大小写/编码绕过
function sanitizeName(name) {
  const blacklist = ['select', 'insert', 'update', 'delete', 'drop', ';'];
  let cleaned = name;
  for (const kw of blacklist) {
    cleaned = cleaned.replace(new RegExp(kw, 'gi'), '');
  }
  return cleaned;
}

/**
 * 为指定归档生成索引记录。
 * @param {string} archiveName - 上层传入的外部提交的归档文件名（不可信）
 * @param {string} ownerTag   - 调用方提供的标签，同样来自外部提交内容
 */
async function indexArchive(archiveName, ownerTag) {
  // 弱过滤：只做黑名单替换，攻击者可用 'SELSELECTECT' 嵌套或 '--' 注释绕过
  const safeName = sanitizeName(archiveName);
  const query = `INSERT INTO archives (name, tag) VALUES ('${safeName}', '${ownerTag}')`;
  await pool.query(query); // sink：字符串拼接进 SQL
}

module.exports = { indexArchive };
```

